from django.db import migrations
from django.contrib.auth.hashers import make_password

def create_system_wallets(apps, schema_editor):
    User = apps.get_model('users', 'User')
    Wallet = apps.get_model('wallets', 'Wallet')

    # Create SYSTEM user
    system_user, created = User.objects.get_or_create(
        username='SYSTEM',
        defaults={
            'email': 'system@digitalwallet.local',
            'is_active': False,
            'is_system': True,
            'password': make_password(None),
        }
    )

    if not created and not system_user.is_system:
        system_user.is_system = True
        system_user.save()

    # Create the 3 base system wallets (EQUITY, INCOME, EXPENSE) in USD by default.
    system_wallets = ['EQUITY', 'INCOME', 'EXPENSE']
    for name in system_wallets:
        Wallet.objects.get_or_create(
            user=system_user,
            name=name,
            currency='USD',
            defaults={
                'status': 'active'
            }
        )

def reverse_system_wallets(apps, schema_editor):
    User = apps.get_model('users', 'User')
    Wallet = apps.get_model('wallets', 'Wallet')
    
    try:
        system_user = User.objects.get(username='SYSTEM')
        Wallet.objects.filter(user=system_user).delete()
        system_user.delete()
    except User.DoesNotExist:
        pass

